function M({registerIndicator:m,sourceValues:d,nulls:c}){m({id:"oa-amat",name:"Archer Moving Averages Trends (AMAT)",category:"Dynamics",placement:"pane",inputs:[{key:"fast",type:"number",label:"Fast Period",default:10,min:1,max:5e3,step:1},{key:"slow",type:"number",label:"Slow Period",default:50,min:2,max:5e3,step:1},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"trend",type:"column",title:"AMAT Trend",style:{color:"#787b86",lineWidth:3},colorBy:({value:a})=>Number.isFinite(a)?a>0?"#4caf50":a<0?"#ff5252":"#787b86":"#787b86"},{key:"strength",type:"line",title:"Trend Strength %",style:{color:"#ffeb3b",lineWidth:2}}],levels:()=>[{price:0,title:"Zero",color:"#787b86",dashed:!0}],calc(a,s){const N=Math.max(1,Math.floor(Number(s.fast)||10)),h=Math.max(2,Math.floor(Number(s.slow)||50)),p=d(a,s.source??"close"),y=2/(N+1),b=2/(h+1),i=a.length,f=new Array(i).fill(NaN),u=new Array(i).fill(NaN);let t=NaN,e=NaN,o=NaN,l=NaN;for(let n=0;n<i;n++){const r=p[n];if(!Number.isFinite(r))continue;Number.isFinite(t)||(t=r,e=r,o=r,l=r),t=y*(r-t)+t,e=b*(r-e)+e;const w=t>e&&t>o&&e>l?1:0,A=t<e&&t<o&&e<l?-1:0;o=t,l=e,f[n]=w+A,u[n]=e===0?NaN:Math.abs(t-e)/e*100}return{trend:c(f),strength:c(u)}}})}export{M as default};
